export interface ViewHelpers {
  /** cents in minor units -> localized currency string */
  money(cents: number, currency: string): string;
}

export const helpers: ViewHelpers = {
  money: (cents, currency) =>
    new Intl.NumberFormat("de-DE", { style: "currency", currency })
      .format(cents / 100),
};
